    image_patch = ImagePatch(image)
    sandwich_patches = image_patch.find("sandwich")
    corned_beef_patches = image_patch.find("corned beef")

    if not sandwich_patches or not corned_beef_patches:
        return image_patch

    sandwich_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in sandwich_patches]
    corned_beef_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in corned_beef_patches]

    for sandwich_center in sandwich_centers:
        for corned_beef_center in corned_beef_centers:
            if abs(sandwich_center[0] - corned_beef_center[0]) < abs(sandwich_center[1] - corned_beef_center[1]):
                return sandwich_patches[sandwich_centers.index(sandwich_center)]

    return sandwich_patches[0]

