    image_patch = ImagePatch(image)
    sandwich_patches = image_patch.find("sandwich")
    meat_patches = image_patch.find("meat")

    if not sandwich_patches or not meat_patches:
        return image_patch

    sandwich_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in sandwich_patches]
    meat_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in meat_patches]

    for i, sandwich_center in enumerate(sandwich_centers):
        for j, meat_center in enumerate(meat_centers):
            if abs(sandwich_center[0] - meat_center[0]) < abs(sandwich_centers[i][0] - sandwich_centers[j][0]):
                sandwich_patches[i], sandwich_patches[j] = sandwich_patches[j], sandwich_patches[i]
                meat_patches[i], meat_patches[j] = meat_patches[j], meat_patches[i]

    for sandwich_patch, meat_patch in zip(sandwich_patches, meat_patches):
        if sandwich_patch.horizontal_center < meat_patch.horizontal_center:
            return sandwich_patch

    return sandwich_patches[0]

