modern_c2_ds.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    giraffe_patches = image_patch.find("giraffe")
    savanna_patches = image_patch.find("savanna")

    if not giraffe_patches:
        return image_patch
    if not savanna_patches:
        return giraffe_patches[0]

    savanna_center_x = sum(p.horizontal_center for p in savanna_patches) / len(savanna_patches)
    giraffe_center_x = sum(p.horizontal_center for p in giraffe_patches) / len(giraffe_patches)

    if giraffe_center_x > savanna_center_x:
        walking_in = [g for g in giraffe_patches if g.horizontal_center > savanna_center_x]
    else:
        walking_in = [g for g in giraffe_patches if g.horizontal_center < savanna_center_x]

    return walking_in[0] if walking_in else giraffe_patches[0]

